Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Local Ltac transport_chunks segs m a bs ::= transport_chunks_fast segs m a bs.
Local Ltac footprint_after_store segs m a bs ::= footprint_after_store_fast segs m a bs.
Local Ltac mem_after_store ::= mem_after_store_fast.
(* [comment removed for export] *)
Local Ltac rt_transport_extra m m' AG ::=
  lept_rt_transport_extra m m' AG;   (* [comment removed for export] *)
  repeat match goal with
  | H : u64arr asegs m ?A ?ws |- _ =>
      first [ apply (u64arr_agree_nw asegs m m' A ws) in H; [ | solve [agree_range AG A ltac:(fun A => acl_dispatch A)] ]
            | idtac "note: dropping u64arr:" H; clear H ]
  end.

(* [comment removed for export] *)
Ltac live_sub_via He :=
  first [ exact He
        | match goal with HS : forall x, In x _ -> In x _ |- _ => solve [apply HS; exact He] end ].
Ltac live_sub_tac ::=
  let e := fresh "e" in let He := fresh "He" in intros e He;
  try solve [destruct He];
  repeat match goal with H : rt_live _ _ = _ |- _ => rewrite H in * end;
  first [ live_sub_via He
        | solve [repeat first [ exact He | eapply live_remove_sub; first [exact He | eassumption] ]]
        | apply live_remove_sub in He; first [ live_sub_via He | apply live_remove_sub in He; live_sub_via He ]
        | unfold km_unlive in He; apply live_remove_sub in He; first [ live_sub_via He | apply live_remove_sub in He; live_sub_via He ] ].

